def fonts():
 s=importlib.util.spec_from_file_location('_fonts',REPO/'content/_fonts.py'); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m.embedded_css()
L=[('▧','An image for the ad','Claude generates none'),('◉','Hands-free thinking','voice mode, while you drive'),('◎','What changed this week','live web, with sources'),('↗','Click through a site for you','computer use'),('✦','A reusable team assistant','a custom GPT'),('▤','A multi-source brief','deep research'),('▦','A photo turned into data','vision, then a table')]
