def rows(items,side):
 return ''.join(f'<div class="row {side}"><span class="ico">{i}</span><div><div class="title">{html.escape(t)}</div><div class="sub">{html.escape(s)}</div></div></div>' for i,t,s in items)
openai=embedded(REPO/'content/assets/icons/openai.svg'); claude=embedded(REPO/'content/assets/icons/claude-color.svg'); av=embedded(REPO/'content/assets/tibi poza_profil_instagram_bw_square_1080.jpg')
css=f'''{fonts()}\n/* FILM-META {{"duration":7.0,"w":1080,"h":1350,"fps":30,"beats":[{{"from":0,"to":3,"name":"reveal"}}]}} */\n:root{{--acc:{ACC};--ink:#111;--muted:#747474}}*{{box-sizing:border-box;margin:0;padding:0}}body{{background:#fff;color:var(--ink);font-family:'DM Sans',Arial,sans-serif}}#film{{position:relative;width:1080px;height:1350px;overflow:hidden;background:#fff}}.header{{position:absolute;top:0;left:0;width:1080px;height:187px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;background:#fff;z-index:5}}.h1{{font-size:58px;font-weight:800;letter-spacing:-2.2px;line-height:1.05}}.h2{{font-size:56px;font-weight:800;letter-spacing:-2.2px;line-height:1.05}}.h2 em{{font-style:normal;color:var(--acc)}}.body{{position:absolute;top:187px;left:0;width:1080px;height:1003px;padding:28px 70px 0;background:#fff}}.compare{{position:relative;width:940px;height:744px;border:3px solid var(--ink);border-bottom:0;border-radius:30px 30px 0 0;background:#fff;overflow:visible}}.compare::before{{content:"";position:absolute;left:50%;top:78px;bottom:0;border-left:1px solid #e2e2e2;transform:translateX(-50%)}}.brand{{position:absolute;top:22px;width:50%;height:52px;display:flex;align-items:center;justify-content:center;gap:12px;font-size:29px;font-weight:800;z-index:2}}.brand.left{{left:0}}.brand.right{{left:50%}}.brand img{{width:36px;height:36px;object-fit:contain}}.brand.right img{{width:40px;height:40px}}.vs{{position:absolute;z-index:3;left:50%;top:55px;transform:translate(-50%,-50%);width:42px;height:42px;border-radius:50%;border:2px solid var(--ink);background:#fff;display:grid;place-items:center;font-size:16px;font-weight:800}}.col{{position:absolute;top:78px;width:50%;padding:0 24px}}.col.left{{left:0}}.col.right{{left:50%}}.row{{height:94px;display:flex;align-items:center;gap:15px;border-top:1px solid #ededed}}.row:first-child{{border-top:0}}.ico{{width:34px;height:34px;display:grid;place-items:center;border:1.5px solid currentColor;border-radius:9px;font-size:21px;line-height:1;flex:0 0 34px}}.row.left{{color:#222}}.row.right{{color:var(--acc)}}.title{{font-size:22px;font-weight:750;line-height:1.15;white-space:nowrap;color:var(--ink)}}.sub{{font-size:16px;font-weight:500;color:var(--muted);margin-top:5px;white-space:nowrap}}.rule{{position:absolute;left:70px;top:792px;width:940px;min-height:150px;border:3px solid var(--ink);border-bottom:0;border-radius:26px 26px 0 0;background:#fff;padding:24px 28px;display:flex;align-items:flex-start;gap:24px;z-index:2}}.rule-label{{background:#111;color:#fff;border-radius:9px;padding:11px 16px;font-size:19px;font-weight:800;white-space:nowrap;line-height:1}}.rule-text{{font-size:25px;line-height:1.25;font-weight:700;max-width:750px}}.rule-text em{{font-style:normal;color:var(--acc)}}.footer{{position:absolute;left:0;top:1190px;width:1080px;height:160px;background:#fff;display:flex;align-items:center;gap:20px;padding-left:70px;z-index:3}}.footer img{{width:58px;height:58px;border-radius:50%;object-fit:cover;border:3px solid var(--acc);padding:2px}}.footer span{{font-size:30px;font-weight:650;white-space:nowrap}}.veil{{position:absolute;left:0;top:187px;width:1080px;height:1003px;background:#000;opacity:.982;z-index:4;pointer-events:none;animation:reveal 3s linear forwards}}@keyframes reveal{{from{{opacity:.982}}to{{opacity:0}}}}'''
html_out=f'''<!doctype html><html><head><meta charset="utf-8"><title>People who use ChatGPT vs Claude</title><style>{css}</style></head><body><main id="film"><header class="header"><div class="h1">People who use</div><div class="h2">ChatGPT vs <em>Claude</em></div></header><section class="body"><div class="compare"><div class="brand left"><img src="{openai}">ChatGPT</div><div class="brand right"><img src="{claude}">Claude</div><div class="vs">VS</div><div class="col left">{rows(L,'left')}</div><div class="col right">{rows(R,'right')}</div></div><div class="rule"><span class="rule-label">THE RULE</span><div class="rule-text">Output is a <em>picture or a click</em>, send it left. Output is a <em>document, a build or a decision</em>, send it right.</div></div></section><footer class="footer"><img src="{av}"><span>Follow for more AI tools and productivity hacks</span></footer><div class="veil"></div></main></body></html>'''
